#include "vibration/supervised_model.hpp"
#include "vibration/sha256.hpp"
#include <algorithm>
#include <cmath>
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace vibration;
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
void near(double a,double b,const char* message){check(std::abs(a-b)<1e-8,message);}
template<class F>void rejects(F call,const char* message){bool failed=false;try{call();}catch(const AnalysisError&){failed=true;}check(failed,message);}
std::string hash(const std::string& value){return sha256_hex(reinterpret_cast<const std::uint8_t*>(value.data()),value.size());}
// Mathematical post-extraction fixtures exercise supervised learning and data
// separation. No generated feature vector is a measured machine observation.
SupervisedSample sample(unsigned cls,unsigned identity,unsigned windows=1){
    const char* names[]{"normal","imbalance","misalignment","looseness"};SupervisedSample s;s.path="supervised-mathematical-"+std::to_string(identity)+".BIN";s.capture_sha256=hash(s.path);s.session_id="supervised-math-session-"+std::to_string(identity);s.label=names[cls];s.operator_updated_at="mathematical-fixture-only";
    for(unsigned i=0;i<windows;++i){SupervisedWindow w;w.valid=true;w.setup_id="math-supervised";w.configuration="abcd1234";w.sample_rate_hz=5000;w.capture_sha256=s.capture_sha256;w.source_session_id=s.session_id;w.source_path=s.path;w.raw_window_sha256=hash(s.path+":"+std::to_string(i));w.first_index=10000*i;w.last_index=w.first_index+9999;for(unsigned j=0;j<69;++j)w.features[j]=(j%4==cls?2.:.1)+.0001*identity;s.windows.push_back(w);}return s;
}
std::vector<SupervisedSample> library(unsigned perClass=2){std::vector<SupervisedSample> out;for(unsigned c=0;c<4;++c)for(unsigned i=0;i<perClass;++i)out.push_back(sample(c,c*10+i));return out;}
SupervisedWindow query(SupervisedWindow w){w.capture_sha256=hash("independent-mathematical-query");w.source_session_id="independent-mathematical-query-session";return w;}
std::string foldModel(const SupervisedValidationReport& report,const std::string& session){for(const auto& fold:report.fold_json)if(fold.find("\"heldout_session\":\""+session+"\"")!=std::string::npos){const auto at=fold.find("\"model_sha256\":\"");check(at!=std::string::npos,"fold model digest field exists");return fold.substr(at+16,64);}throw std::runtime_error("heldout fixture fold missing");}
}
int main(){try{
    const auto data=library();SupervisedTrainOptions options;options.algorithm=SupervisedAlgorithm::LinearSoftmax;options.feature_set=SupervisedFeatureSet::All69;options.iterations=180;const auto model=fit_supervised_model(data,"mathematical-supervised",options);
    check(model.kind=="supervised_linear_softmax_v1"&&model.training_windows==8&&model.training_file_counts==std::array<unsigned,4>{2,2,2,2},"true supervised classifier retains labelled file counts");
    check(std::any_of(model.weights.begin(),model.weights.end(),[](double value){return std::abs(value)>1e-5;}),"training fits nonzero learned coefficients rather than storing nearest reference vectors");
    for(unsigned c=0;c<4;++c){const auto result=infer_supervised(query(data[2*c].windows[0]),model);check(result.classification==data[2*c].label&&result.status=="trained_four_class_result"&&!result.validated&&!result.training_replay,"learned discriminants give four classes on separated mathematical features");near(result.scores[0]+result.scores[1]+result.scores[2]+result.scores[3],100,"four uncalibrated model scores sum to 100");}
    auto permuted=data;for(auto& s:permuted){if(s.label=="normal")s.label="looseness";else if(s.label=="looseness")s.label="normal";}
    const auto learnedPermutation=fit_supervised_model(permuted,"mathematical-supervised",options);check(infer_supervised(query(data[0].windows[0]),learnedPermutation).classification=="looseness"&&learnedPermutation.weights!=model.weights,"changing supervised targets changes learned coefficients and predictions for the same waveform features");
    const auto text=supervised_model_text(model);check(supervised_model_text(parse_supervised_model(text))==text,"learned weights, training-only normalization and source identities roundtrip exactly");rejects([&]{parse_supervised_model(text+"validated=true\n");},"model artifact cannot inject a validation claim");rejects([&]{parse_supervised_model(text+"kind=another\n");},"duplicate persisted kind fails closed");
    auto reordered=data;std::reverse(reordered.begin(),reordered.end());check(supervised_model_text(fit_supervised_model(reordered,"mathematical-supervised",options))==text,"training order cannot change learned model or source provenance");
    auto longFile=data;longFile[0]=sample(0,0,32);const auto equalSession=fit_supervised_model(longFile,"mathematical-supervised",options);for(unsigned j=0;j<69;++j){near(equalSession.mean[j],model.mean[j],"32 identical windows cannot give one session 32 normalization votes");near(equalSession.scale[j],model.scale[j],"session weighting preserves training scales");}for(unsigned j=0;j<model.weights.size();++j)near(equalSession.weights[j],model.weights[j],"session weighting preserves fitted coefficients under repeated within-file windows");
    auto segments=data;auto extra=sample(0,1000);extra.session_id=data[0].session_id;extra.windows[0].source_session_id=extra.session_id;extra.windows[0].features=data[0].windows[0].features;segments.push_back(extra);const auto segmented=fit_supervised_model(segments,"mathematical-supervised",options);check(segmented.training_file_counts[0]==3&&segmented.independent_session_counts[0]==2,"two segments of one capture are not two independent sessions");for(unsigned j=0;j<model.weights.size();++j)near(segmented.weights[j],model.weights[j],"same-session segments divide a single session weight");
    const auto one=library(1);check(infer_supervised(query(one[0].windows[0]),fit_supervised_model(one)).classification=="normal","one labelled source per class can train a four-class result");check(!evaluate_supervised_models(one,options).metrics_available,"one source per class cannot fabricate an independent heldout metric");
    auto overlap=data;for(auto& s:overlap)for(auto& w:s.windows)w.features.fill(1);const auto overlapping=fit_supervised_model(overlap,"overlap",options);check(infer_supervised(query(overlap[0].windows[0]),overlapping).classification!="unknown","ambiguous finite waveform still returns highest class; no margin rejection class is introduced");
    auto extreme=query(data[0].windows[0]);extreme.features.fill(1e6);check(infer_supervised(extreme,model).classification!="unknown","finite out-of-training-range waveform still returns the best learned class");extreme.warnings={"raw_adc_clipping_CH1"};check(infer_supervised(extreme,model).status=="trained_four_class_result","input clipping warning does not suppress computed four-class result");
    auto warned=data;warned[0].windows[0].warnings={"raw_adc_clipping_CH1"};check(fit_supervised_model(warned,"warned",options).training_warning_windows==1,"valid warning windows are included with an explicit training count");
    auto invalid=query(data[0].windows[0]);invalid.valid=false;check(infer_supervised(invalid,model).classification=="unknown","unavailable/corrupt input cannot fabricate a class");invalid=query(data[0].windows[0]);invalid.synthetic=true;check(infer_supervised(invalid,model).classification=="unknown","synthetic source cannot fabricate a real machine classification");invalid=query(data[0].windows[0]);invalid.features[0]=std::numeric_limits<double>::quiet_NaN();check(infer_supervised(invalid,model).classification=="unknown","nonfinite data cannot fabricate a class");invalid=query(data[0].windows[0]);invalid.configuration="abcd1235";check(infer_supervised(invalid,model).status=="configuration_mismatch","actual ADC/FIR/feature identity remains checked");check(infer_supervised(data[0].windows[0],model).training_replay,"training source replay stays explicit");
    auto missing=data;missing.erase(missing.begin(),missing.begin()+2);rejects([&]{fit_supervised_model(missing);},"missing a class cannot produce a four-class learned model");auto copied=data;copied.push_back(data[0]);rejects([&]{fit_supervised_model(copied);},"copied sources cannot count as new training data");auto conflict=data;conflict[2].session_id=data[0].session_id;conflict[2].windows[0].source_session_id=data[0].session_id;rejects([&]{fit_supervised_model(conflict);},"one session cannot train under conflicting operator targets");
    const auto validation=evaluate_supervised_models(data,options);check(validation.metrics_available&&validation.heldout_sessions==8&&validation.windows==8&&!validation.validated,"whole-session heldout validation counts sessions rather than random windows");near(validation.accuracy,1,"ideal separated mathematical sessions are recognized in heldout software fixture only");
    const auto leakageData=library(3);const auto before=evaluate_supervised_models(leakageData,options);auto changed=leakageData;changed[0]=sample(0,0,4);changed[0].label="imbalance";for(auto& w:changed[0].windows)w.features.fill(1e6);const auto after=evaluate_supervised_models(changed,options);check(foldModel(before,leakageData[0].session_id)==foldModel(after,leakageData[0].session_id),"heldout label, features and window count cannot affect that fold's training coefficients or normalization");
    SupervisedTrainOptions forestOptions;const auto forest=fit_supervised_model(data,"mathematical-forest",forestOptions);check(forest.kind=="supervised_random_forest_v1"&&forest.forest.size()==32&&supervised_active_feature_indices(forestOptions).size()==42,"fixed shallow forest protocol and selected 42-feature mask are explicit");
    for(unsigned c=0;c<4;++c)check(infer_supervised(query(data[2*c].windows[0]),forest).classification==data[2*c].label,"learned tree splits distinguish mathematical class patterns");
    const auto forestText=supervised_model_text(forest);check(supervised_model_text(parse_supervised_model(forestText))==forestText,"every learned split, leaf vote and mask persists exactly");check(supervised_model_text(fit_supervised_model(reordered,"mathematical-forest",forestOptions))==forestText,"fixed-seed forest is deterministic under source enumeration changes");
    auto maskedQuery=query(data[0].windows[0]);const auto maskedBase=infer_supervised(maskedQuery,forest);for(unsigned ch=0;ch<3;++ch)for(unsigned j=12;j<21;++j)maskedQuery.features[ch*21+j]=1e6;check(infer_supervised(maskedQuery,forest).scores==maskedBase.scores,"excluded packet coordinates cannot affect RF42 classification");
    auto invalidForest=forest;invalidForest.forest[0].nodes[0].left=0;rejects([&]{supervised_model_text(invalidForest);},"cyclic or backward learned tree links fail closed");
    const auto forestBefore=evaluate_supervised_models(leakageData,forestOptions),forestAfter=evaluate_supervised_models(changed,forestOptions);check(foldModel(forestBefore,leakageData[0].session_id)==foldModel(forestAfter,leakageData[0].session_id),"heldout label/features cannot leak into tree splits or training scales");
    std::cout<<"PASS: supervised learned-target response, four-class inference, session-balanced training, no random-window leakage, source/config/data contracts, heldout separation and persistence; mathematical fixtures only, no machine accuracy measured.\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
